Item.sk_method_code:
/*
    マルQページ作成時の利用者(同室課)選択ボタン押下時の動作
*/

    const iomInv = aras.IomInnovator;
    const targetType = this.itemTypeName;
debugger;
    // 無名async関数による非同期処理の即時実行
    (async (targetType) => {
        // Projectアイテム選択用非同期関数
        async function selectProject() {

            // ダイアログ表示用パラメータ設定
            const dialogParams = {
                title: "利用者(同室課)選択",
                type: 'SearchDialog',
                itemtypeName: 'identity',
                multiselect: false,
            };

            // 同室課選択ダイアログ表示
            try {
                const selProjectDialog = await top.ArasModules.MaximazableDialog.show(
                    'iframe',
                    dialogParams
                ).promise;
                return selProjectDialog;

            } catch (error) {
                // エラーハンドリング
                aras.alertError('Error:' + error);
            }
        }

        // 選択結果の取得
        const selectResult = await selectProject();
        if (!selectResult.itemID) {
            return;
        }

        // 選択した値を設定
        elements = document.querySelectorAll('input');
        for (var i = 0; i < elements.length; i++) {
    
            var ele = elements[i];
            var eleName = ele.name;

            // 設定値の取得
            if (eleName == "h4_frm_managed_by_id") {
debugger;
                ele.value = selectResult.keyed_name;
                ele.id = selectResult.itemID;
                continue;
            }
        }

    })(targetType);
    
return;

/*
    マルQページ初期値設定画面の設定を取得
*/

    const iomInv = aras.IomInnovator;


    // 入力フィールドを全て取得
    var elements = document.querySelectorAll('select');

    // 入力値の取得
    var strDeltaVersion = "";
    var strDept = "";
    var strGr = "";
    var strSec = "";
    var strEvent = "";
    var strEventLabel = "";
    var strMy = "";
    var strDestination = "";
    var strModelName = "";
    var strModelNameId = "";
    var strModelCode = "";
    var strManagedByIdName = "";
    var strManagedById = "";
    var strUnit = "";
    for (var i = 0; i < elements.length; i++) {
        var ele = elements[i];
        var eleName = ele.name;

        // 設定値の取得
        if (eleName == "h4_frm_event") {
            if (ele.value != "") {
                strEvent = ele.value;
                strEventLabel = ele.options[ele.selectedIndex].text;
            }
            continue;
        }
    }

    elements = document.querySelectorAll('input');
    for (var i = 0; i < elements.length; i++) {

        var ele = elements[i];
        var eleName = ele.name;


        // 評価単位の取得 室課
        if (eleName == "h4_frm_unit") {
            strUnit = ele.value;
            continue;
        }

        // 設定値の取得 室課
        if (eleName == "h4_frm_Dept") {
            strDept = ele.value;
            continue;
        }

        // 設定値の取得 グループ
        if (eleName == "h4_frm_Gr") {
            strGr = ele.value;
            continue;
        }

        // 設定値の取得 セクション
        if (eleName == "h4_frm_Sec") {
            strSec = ele.value;
            continue;
        }

        // 設定値の取得 ⊿バージョン
        if (eleName == "h4_frm_DeltaVersion") {
            strDeltaVersion = ele.value.replace("⊿", "");
            continue;
        }

        // 設定値の取得
        if (eleName == "h4_frm_my") {
            strMy = ele.value;
            continue;
        }

        // 設定値の取得
        if (eleName == "h4_frm_model_name") {
            strModelName = ele.value;
            strModelNameId = ele.id;
            continue;
        }

        // 設定値の取得
        if (eleName == "h4_frm_model_code") {
            strModelCode = ele.value;
            continue;
        }

        // 仕向け地の取得        
        if (eleName == "h4_frm_Destination") {
            strDestination = ele.value.replaceAll(",", "@");
            continue;
        }
        
        // 利用者(同室課)
        if (eleName == "h4_frm_managed_by_id") {
            strManagedByIdName = ele.value;
            strManagedById = ele.id;
            continue;
        }

    }

    // 入力値確認
    if (strModelName == "") {

        var userMsgItem = iomInv.newItem("UserMessage","get");
        userMsgItem.setAttribute("select","text");
        var errName = "h4_C_E_0402";
        userMsgItem.setProperty("name",errName);
        userMsgItem = userMsgItem.apply();
        var msg = userMsgItem.getProperty("text","");
        aras.AlertError(msg);

        return;
    } else if (strModelCode == "") {

        var userMsgItem = iomInv.newItem("UserMessage","get");
        userMsgItem.setAttribute("select","text");
        var errName = "h4_C_E_0403";
        userMsgItem.setProperty("name",errName);
        userMsgItem = userMsgItem.apply();
        var msg = userMsgItem.getProperty("text","");
        aras.AlertError(msg);

        return;
    } else if (strDestination == "") {
        
        var userMsgItem = iomInv.newItem("UserMessage","get");
        userMsgItem.setAttribute("select","text");
        var errName = "h4_C_E_0405";
        userMsgItem.setProperty("name",errName);
        userMsgItem = userMsgItem.apply();
        var msg = userMsgItem.getProperty("text","");
        aras.AlertError(msg);

        return;
    } else if (strManagedByIdName == "") {
        
        var userMsgItem = iomInv.newItem("UserMessage","get");
        userMsgItem.setAttribute("select","text");
        var errName = "h4_C_E_0406";
        userMsgItem.setProperty("name",errName);
        userMsgItem = userMsgItem.apply();
        var msg = userMsgItem.getProperty("text","");
        aras.AlertError(msg);

        return;
    }

    // ⊿バージョンと機種呼称のマップ確認
    var lstModelNames = iomInv.newItem("List", "get");
    lstModelNames.setAttribute("select", "id")
    lstModelNames.setProperty("name", "h4_ModelName");
    lstModelNames = lstModelNames.apply();

    var filterValues = iomInv.newItem("Filter Value", "get");
    filterValues.setAttribute("select", "filter,label,value");
    filterValues.setProperty("source_id", lstModelNames.getID());
    filterValues = filterValues.apply();

    // 機種呼称が⊿バージョンとマップしたデータか？
    var isFound = false;
    for (var i = 0; i < filterValues.getItemCount(); i++) {

        var wkItem = filterValues.getItemByIndex(i);
        var strFilter = wkItem.getProperty("filter");

        if (strFilter == strDeltaVersion) {
            var val = wkItem.getProperty("value");
            if (val == strModelName) {
                isFound = true;
                break;
            }
        }
    }
    
    if (! isFound) {

        var userMsgItem = iomInv.newItem("UserMessage","get");
        userMsgItem.setAttribute("select","text");
        var errName = "h4_C_E_0404";
        userMsgItem.setProperty("name",errName);
        userMsgItem = userMsgItem.apply();
        var msg = userMsgItem.getProperty("text","");
        aras.AlertError(msg);

        return;
    }
    debugger;
    // 同じ [室課] [機種呼称] [機種コード] [イベント] のマルQページが存在しない事
    var lstMaruQPage = iomInv.newItem("h4_MQPage", "get");
    lstMaruQPage.setAttribute("select", "id, h4_delta_version, h4_dept, h4_model_name, h4_model_code, h4_event");
//    lstMaruQPage.setProperty("h4_delta_version", strDeltaVersion);      // 同一⊿バージョンのみチェック対象
    lstMaruQPage.setProperty("h4_dept", strDept);
    lstMaruQPage.setProperty("h4_model_name", strModelNameId);
    lstMaruQPage.setProperty("h4_model_code", strModelCode);
    lstMaruQPage.setProperty("h4_event", strEvent);

    var whereList = [];
    if(strGr != ""){ lstMaruQPage.setProperty("h4_group", strGr); }
    else {whereList.push("([h4_MQPage].h4_group IS NULL OR [h4_MQPage].h4_group = '')");}

    if(strSec != ""){ lstMaruQPage.setProperty("h4_section", strSec); }
    else {whereList.push("([h4_MQPage].h4_section IS NULL OR [h4_MQPage].h4_section = '')");}

    if(whereList.length >= 1)
    {
        lstMaruQPage.setAttribute("where", whereList.join(" AND "));
    }

    lstMaruQPage = lstMaruQPage.apply();

    // 個別イベントはいらない
    var lstTargetItems = [];
    for (var i = 0; i < lstMaruQPage.getItemCount(); i++) {

        var targetMaruQPage = lstMaruQPage.getItemByIndex(i);
        var targetEvent = targetMaruQPage.getProperty("h4_event");
        if (targetEvent.toLowerCase() == "special") {
            continue;
        }
        lstTargetItems.push(targetMaruQPage);
    }

    if (lstTargetItems.length != 0) {

        // 既に同じ [室課] [機種呼称] [機種コード] [イベント] が存在している
        var userMsgItem = iomInv.newItem("UserMessage","get");
        userMsgItem.setAttribute("select","text");
        var errName = "h4_C_E_0408";
        userMsgItem.setProperty("name",errName);
        userMsgItem = userMsgItem.apply();
        var msg = userMsgItem.getProperty("text","");
        aras.AlertError(msg);
    } else {
        // ダイアログクローズ処理（カンマ[,]区切り文字列生成、0: イベント, 1: MY, 2: 仕向け, 3: 機種コード, 機種呼称. 機種呼称ID, 利用者(同室課), 評価単位,グループ,セクション
        parent.dialogArguments.dialog.close(strEventLabel + "," + strMy + "," + strDestination + "," + strModelCode + "," + strModelName + "," + strModelNameId + "," + strManagedById + "," + strUnit + "," + strGr + "," + strSec);
    }


return;

/*
    マルQページのイベント設定ダイアログの表示
*/


// 無名async関数による非同期処理の即時実行
(async () => {

    const iomInv = aras.IomInnovator;
    const itemTypeName = this.itemTypeName;

    // フォーム上の仕向け値の取得
    var elements = document.querySelectorAll('input');
    var strDestinations = "";
    for (var i = 0; i < elements.length; i++) {

        var ele = elements[i];
        var eleName = ele.name;

        // 仕向け値以外はスキップ
        if (ele.type == "text") {
            if (eleName != "h4_frm_Destination") {
                continue;
            }
        } else {
            continue;
        }

        if (ele.value == "undefined") {
            break;
        }

        strDestinations = ele.value;
        break;      // 仕向け値はフィールドが一つの為
    }

    // 仕向け値選択フォームの表示
    var formId = aras.getFormId('h4_DATFormat_Input_Init_DestVal');
    var form = aras.getFormForDisplay(formId);
    var topWnd = top.aras.getMostTopWindowWithAras();
    var wnd = topWnd ? topWnd : window;

    var params = {
        title: "仕向け設定",
        formId: form.node.getAttribute('id'),
        destinations: strDestinations,
        dialogWidth: 460,
        dialogHeight: 200,
        content: 'ShowFormAsADialog.html'
    };

    topWnd.ArasModules.MaximazableDialog.show('iframe', params).promise.then(function(dlgRes) {
        if (!dlgRes) {
            return;
        }
        
        // 選択した仕向け地の値を仕向けに設定
        elements = document.querySelectorAll('input');
        for (var i = 0; i < elements.length; i++) {
    
            var ele = elements[i];
            var eleName = ele.name;

            // 設定値の取得
            if (eleName == "h4_frm_Destination") {
                var strDests = [];
                for (var j = 0; j < dlgRes.length; j++) {
                    strDests.push(dlgRes[j]);
                }
                ele.value = strDests;
                break;
            }
        }
    });

})();

/*
    マルQページ作成時の機種呼称選択ボタン押下時の動作
*/

    const iomInv = aras.IomInnovator;
    const targetType = this.itemTypeName;

    // 無名async関数による非同期処理の即時実行
    (async (targetType) => {
        // Projectアイテム選択用非同期関数
        async function selectProject() {

            // ダイアログ表示用パラメータ設定
            const dialogParams = {
                title: "Project選択",
                type: 'SearchDialog',
                itemtypeName: 'HRDPMTypModelProject',
                multiselect: false,
            };

            // Project選択ダイアログ表示
            try {
                const selProjectDialog = await top.ArasModules.MaximazableDialog.show(
                    'iframe',
                    dialogParams
                ).promise;
                return selProjectDialog;

            } catch (error) {
                // エラーハンドリング
                aras.alertError('Error:' + error);
            }
        }

        // Project選択結果の取得
        const selectResult = await selectProject();
        if (!selectResult.itemID) {
            return;
        }


        // 選択したProjectの値を機種呼称へ設定
        elements = document.querySelectorAll('input');
        for (var i = 0; i < elements.length; i++) {
    
            var ele = elements[i];
            var eleName = ele.name;

            // 機種呼称の設定
            if (eleName == "h4_frm_model_name") {
                ele.value = selectResult.keyed_name;
                ele.id = selectResult.itemID;
                continue;
            }

            // Myの設定
            if (eleName == "h4_frm_my") {
                var strMy = aras.getItemProperty(selectResult.item, "iq_model_year", "");
                ele.value = strMy;
                continue;
            }

        }

    })(targetType);
    
return;

/*
    マルQページの初期値設定画面の初期化メソッド
*/

    // 引数からプロパティタイプの取得
    var strDeltaVersion = parent.frameElement.dialogArguments.deltaVersion;
    var strDept = parent.frameElement.dialogArguments.dept;
    var strGr = parent.frameElement.dialogArguments.grp;
    var strSec = parent.frameElement.dialogArguments.sec;
    var events = parent.frameElement.dialogArguments.eventValue;
    var eventLabel = parent.frameElement.dialogArguments.eventLabel;
    var selEvent = parent.frameElement.dialogArguments.selEvent;
    var mys = parent.frameElement.dialogArguments.my;
    var destinations = parent.frameElement.dialogArguments.destination;
    var strIsUseWF =  parent.frameElement.dialogArguments.isUseWF;
    var modelName = parent.frameElement.dialogArguments.modelName;
    var modelNameId = parent.frameElement.dialogArguments.modelNameId;
    var modelCode = parent.frameElement.dialogArguments.modelCode;
    var managedById = parent.frameElement.dialogArguments.managedById;
    var unit = parent.frameElement.dialogArguments.unit;

    const selectElements = document.querySelectorAll('select');
    for (var i = 0; i < selectElements.length; i++) {

        var ele = selectElements[i];
        var eleName = ele.name;

        // イベントのアイテム追加
        if (eleName.indexOf("Event") == 0) {
            for (var j = 0; j < eventLabel.length; j++) {
                var newOption = document.createElement('option');
                newOption.value = events[j];
                newOption.text = eventLabel[j];
                ele.appendChild(newOption);
            }
        }

        if (eleName.indexOf("Destination") == 0) {
            for (var j = 0; j < destinations.length; j++) {
                var newOption = document.createElement('option');
                newOption.text = destinations[j];
                newOption.value = destinations[j];
                ele.appendChild(newOption);
            }
        }

    }

    // 全ての入力要素を取得
    const inputElements = document.querySelectorAll('input');
    for (var i = 0; i < inputElements.length; i++) {

        var ele = inputElements[i];
        var eleName = ele.name;

        // 評価単位
        if (eleName.indexOf("Unit") == 0) {
            ele.name = "h4_frm_unit";
            ele.required = false;
            ele.readOnly = false;
            ele.value = unit;
        }

        // ⊿バージョン入力フィールド
        if (eleName.indexOf("DeltaVersion") == 0) {
            ele.name = "h4_frm_DeltaVersion";
            ele.required = true;
            ele.readOnly = true;
            ele.value = "⊿" + strDeltaVersion;
        }

        // 室課入力フィールド
        if (eleName.indexOf("Dept") == 0) {
            ele.name = "h4_frm_Dept";
            ele.required = true;
            ele.readOnly = true;
            ele.value = strDept;
        }

        // グループ入力フィールド
        if (eleName.indexOf("Gr") == 0) {
            ele.name = "h4_frm_Gr";
            ele.required = false;
            ele.readOnly = false;
            ele.value = strGr;
        }

        // セクション入力フィールド
        if (eleName.indexOf("Sec") == 0) {
            ele.name = "h4_frm_Sec";
            ele.required = false;
            ele.readOnly = false;
            ele.value = strSec;
        }
            
        // MY入力フィールド
        if (eleName.indexOf("My") == 0) {
            ele.name = "h4_frm_my";
            ele.required = true;
            ele.readOnly = true;
            ele.value = mys;
        }

        // ワークフローの有無
        if (eleName.indexOf("UseWF") == 0) {
            ele.name = "h4_frm_Use_WF";
            ele.disabled  = true;
            if (strIsUseWF == "1") {
                ele.checked = true;
            }
        }

        // 機種呼称
        if (eleName.indexOf("ModelName") == 0) {
            ele.name = "h4_frm_model_name";
            ele.required = true;
            ele.readOnly = true;
            ele.value = modelName;
            ele.id = modelNameId;
        }
        
        // 機種コード
        if (eleName.indexOf("ModelCode") == 0) {
            ele.name = "h4_frm_model_code";
            ele.required = false;
//            ele.readOnly = false;
            ele.value = modelCode;
        }

        // 仕向け
        if (eleName.indexOf("Destination") == 0) {
            ele.name = "h4_frm_Destination";
            ele.required = true;
            ele.readOnly = true;
            ele.value = destinations;
        }

        // 利用者(同室課)
        if (eleName.indexOf("Managed_by_id") == 0) {
            ele.name = "h4_frm_managed_by_id";
            ele.required = true;
            ele.readOnly = true;
            ele.value = "";
        }

    }

    // イベントアップの初期値設定
    for (var i = 0; i < selectElements.length; i++) {

        var ele = selectElements[i];
        var eleName = ele.name;

        // イベント
        if (eleName.indexOf("Event") == 0) {
            ele.name = "h4_frm_event";
            ele.value = selEvent;
        }


    }


return;
